import{_ as a,o as n,c as s,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"Digital Employee Architecture V0.2","description":"","frontmatter":{"title":"Digital Employee Architecture V0.2","outline":"deep"},"headers":[],"relativePath":"digital-employee/architecture.md","filePath":"digital-employee/architecture.md","lastUpdated":1785568227000}'),t={name:"digital-employee/architecture.md"};function o(l,e,p,r,d,c){return n(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="digital-employee-architecture-v0-2-数字员工架构-v0-2" tabindex="-1">Digital Employee Architecture V0.2 / 数字员工架构 V0.2 <a class="header-anchor" href="#digital-employee-architecture-v0-2-数字员工架构-v0-2" aria-label="Permalink to &quot;Digital Employee Architecture V0.2 / 数字员工架构 V0.2&quot;">​</a></h1><blockquote><p>Governing architecture baseline / 纲领性架构基线<br> Status: Active Research Baseline / 状态：现行研究基线<br> Updated: 2026-07-31</p></blockquote><h2 id="executive-definition-核心定义" tabindex="-1">Executive definition / 核心定义 <a class="header-anchor" href="#executive-definition-核心定义" aria-label="Permalink to &quot;Executive definition / 核心定义&quot;">​</a></h2><p>A Digital Employee is a persistent, software-defined organizational work unit. Externally it is represented by a <strong>Position</strong>; internally it is executed by a <strong>managed work team</strong>.</p><p>数字员工是组织内部一个由软件定义、持久存在的工作单元：对外表现为<strong>岗位（Position）</strong>，对内由**受管理的工作团队（Managed Work Team）**执行。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital Employee</span></span>
<span class="line"><span>├── External contract: Position</span></span>
<span class="line"><span>└── Internal execution: Managed Work Team</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数字员工</span></span>
<span class="line"><span>├── 对外契约：岗位</span></span>
<span class="line"><span>└── 对内执行：受管理工作团队</span></span></code></pre></div><p>A model, prompt, Agent session, workflow, script, avatar, or tool may be an implementation component, but none alone defines a Digital Employee.</p><p>模型、Prompt、Agent 会话、工作流、脚本、拟人形象或工具都可以成为实现组件，但任何一个都不足以单独定义数字员工。</p><h2 id="stable-organizational-contract-稳定组织契约" tabindex="-1">Stable organizational contract / 稳定组织契约 <a class="header-anchor" href="#stable-organizational-contract-稳定组织契约" aria-label="Permalink to &quot;Stable organizational contract / 稳定组织契约&quot;">​</a></h2><p>The stable layer contains:</p><ul><li>position purpose and responsibility;</li><li>allowed and prohibited work;</li><li>Work Catalog;</li><li>authority and permission boundaries;</li><li>completion contract;</li><li>evidence requirements;</li><li>evaluation and lifecycle policy.</li></ul><p>稳定层包括：岗位使命与职责、允许与禁止事项、工作目录、权限边界、完成契约、证据要求、评估与生命周期政策。</p><p>The execution layer remains replaceable:</p><ul><li>Agent and model providers;</li><li>sessions and temporary teams;</li><li>deterministic rules;</li><li>Browser, Windows, API, source and file tools;</li><li>runtime deployment strategy.</li></ul><p>即使底层模型、Agent Provider、Session、工具或执行策略更换，岗位契约仍应保持有效。</p><h2 id="object-hierarchy-对象分层" tabindex="-1">Object hierarchy / 对象分层 <a class="header-anchor" href="#object-hierarchy-对象分层" aria-label="Permalink to &quot;Object hierarchy / 对象分层&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Position</span></span>
<span class="line"><span>  → Work Catalog</span></span>
<span class="line"><span>    → WorkOrder</span></span>
<span class="line"><span>      → Plan</span></span>
<span class="line"><span>        ↔ Workflow</span></span>
<span class="line"><span>          → Operation Node</span></span>
<span class="line"><span>            → Semantic Action Plan</span></span>
<span class="line"><span>              → Tool Call</span></span>
<span class="line"><span>                → Run</span></span>
<span class="line"><span>                  → Outcome</span></span></code></pre></div><ul><li><strong>Position</strong> defines long-term responsibility.</li><li><strong>WorkOrder</strong> is one bounded request.</li><li><strong>Plan</strong> describes how this instance will be handled.</li><li><strong>Workflow</strong> is a governed, reusable method proven by real runs.</li><li><strong>Operation Node</strong> is the smallest business-meaningful and verifiable work unit.</li><li><strong>Tool Call</strong> is a low-level action and does not prove business success.</li><li><strong>Outcome</strong> is the governed business result.</li></ul><p>岗位定义长期职责；WorkOrder 表示本次工作；Plan 是本次方案；Workflow 是经真实运行验证的可复用方法；Operation Node 是可验证的业务工作单元；Tool Call 只是底层动作；Outcome 才是受治理的业务结果。</p><h2 id="ai-native-workflow-ai-原生工作流" tabindex="-1">AI-native workflow / AI 原生工作流 <a class="header-anchor" href="#ai-native-workflow-ai-原生工作流" aria-label="Permalink to &quot;AI-native workflow / AI 原生工作流&quot;">​</a></h2><p>A Digital Employee must avoid two extremes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Everything fixed → degenerates into RPA</span></span>
<span class="line"><span>Only a goal prompt → degenerates into an uncontrolled Agent</span></span></code></pre></div><p>The intended middle ground is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Fixed boundaries, authority, state and completion contracts</span></span>
<span class="line"><span>+</span></span>
<span class="line"><span>Adaptive AI planning and execution inside those constraints</span></span>
<span class="line"><span>+</span></span>
<span class="line"><span>Reconstructable evidence, verification, recovery and publication gates</span></span></code></pre></div><p>正确中间态是：固定职责、权限、状态与完成契约；AI 在约束内自主规划和执行；全过程留下可重建证据，并具有验证、恢复和发布门禁。</p><h2 id="runtime-boundary-runtime-边界" tabindex="-1">Runtime boundary / Runtime 边界 <a class="header-anchor" href="#runtime-boundary-runtime-边界" aria-label="Permalink to &quot;Runtime boundary / Runtime 边界&quot;">​</a></h2><p><strong>CodeFlowMu is the Digital Employee Runtime.</strong> Cursor, Codex, OpenHands, model APIs and local models are replaceable Providers or adapters.</p><p><strong>CodeFlowMu 本身才是数字员工 Runtime。</strong> Cursor、Codex、OpenHands、模型 API 与本地模型属于可替换 Provider 或 Adapter。</p><p>CodeFlowMu Runtime is responsible for:</p><ul><li>Work Manager / PM;</li><li>Agent registry and sessions;</li><li>task dispatch and FCoP lifecycle;</li><li>workflow interpretation and node execution;</li><li>timeout, retry, checkpoint and recovery;</li><li>TeamPolicy and completion gates;</li><li>Event Outbox and TMPA projection;</li><li>observability, human gates and evaluation.</li></ul><h2 id="tmpa-and-fcop-tmpa-与-fcop" tabindex="-1">TMPA and FCoP / TMPA 与 FCoP <a class="header-anchor" href="#tmpa-and-fcop-tmpa-与-fcop" aria-label="Permalink to &quot;TMPA and FCoP / TMPA 与 FCoP&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA</span></span>
<span class="line"><span>  AI work data and governance architecture</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FCoP</span></span>
<span class="line"><span>  Formal, coarse-grained coordination and responsibility protocol</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CodeFlowMu</span></span>
<span class="line"><span>  Digital Employee development and work runtime</span></span></code></pre></div><p>TMPA provides five unified work-data types: <strong>Profile, Event, Message, Index, Knowledge</strong>. It governs source, writer, time, version, evidence, verification, publication and knowledge promotion.</p><p>FCoP manages formal responsibility handoffs through TASK, REPORT, ISSUE, REVIEW and lifecycle transitions. It should not record every click or tool call.</p><p>Three recording levels remain distinct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Runtime Tool Trace     — debugging-level actions</span></span>
<span class="line"><span>TMPA Semantic Event    — business-meaningful facts</span></span>
<span class="line"><span>FCoP Coordination      — formal responsibility handoffs</span></span></code></pre></div><h2 id="completion-model-完成模型" tabindex="-1">Completion model / 完成模型 <a class="header-anchor" href="#completion-model-完成模型" aria-label="Permalink to &quot;Completion model / 完成模型&quot;">​</a></h2><p>A Runtime process finishing does not prove business correctness. Formal completion is a conjunction:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">completion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  business_state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">criteria_satisfied</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  runtime_state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">completed</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  coordination_state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">done</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  publication_state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">final</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  verification_state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passed</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  human_authority_state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">satisfied_or_not_required</span></span></code></pre></div><h2 id="knowledge-and-learning-知识与进化" tabindex="-1">Knowledge and learning / 知识与进化 <a class="header-anchor" href="#knowledge-and-learning-知识与进化" aria-label="Permalink to &quot;Knowledge and learning / 知识与进化&quot;">​</a></h2><p>Work experience does not directly overwrite formal knowledge.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run / Failure / EVAL</span></span>
<span class="line"><span>→ Knowledge or Workflow Candidate</span></span>
<span class="line"><span>→ Review and safe-data regression</span></span>
<span class="line"><span>→ Versioned publication</span></span>
<span class="line"><span>→ Governed Knowledge</span></span></code></pre></div><p>自我学习必须采用候选、复核、回归、版本化与可回滚机制，避免把一次偶然经验固化成正式规则。</p><h2 id="sme-first-economics-中小企业优先与经济性" tabindex="-1">SME-first economics / 中小企业优先与经济性 <a class="header-anchor" href="#sme-first-economics-中小企业优先与经济性" aria-label="Permalink to &quot;SME-first economics / 中小企业优先与经济性&quot;">​</a></h2><p>Persistent does not mean an LLM consumes tokens continuously. What remains persistent is the Position, identity, authority, work history, state, evidence, workflow versions, evaluation and cost records. Compute activates when work arrives.</p><p>评估应包括业务完成率、质量、证据完整度、返工、恢复、人工介入、API/Token 成本、节点成本与实际创造价值。</p><h2 id="decisive-engineering-proof-决定性工程证明" tabindex="-1">Decisive engineering proof / 决定性工程证明 <a class="header-anchor" href="#decisive-engineering-proof-决定性工程证明" aria-label="Permalink to &quot;Decisive engineering proof / 决定性工程证明&quot;">​</a></h2><p>The architecture is proven only when the same CodeFlowMu Core can run both:</p><ol><li>the existing Open Dev Team as a Software Development Digital Employee; and</li><li>a materially different business employee such as the Saige short-rental Digital Employee,</li></ol><p>without adding business-specific role and workflow logic to Core.</p><p>只有同一 Core 能在不写入业务专用 Core 逻辑的前提下，同时运行软件开发岗位与赛格短租岗位，CodeFlowMu 才真正跨过“多 Agent 开发团队”到“数字员工引擎”的门槛。</p><h2 id="open-agenda-待讨论议题" tabindex="-1">Open agenda / 待讨论议题 <a class="header-anchor" href="#open-agenda-待讨论议题" aria-label="Permalink to &quot;Open agenda / 待讨论议题&quot;">​</a></h2><ul><li>minimum formal fields for Position, WorkOrder, Workflow, Node, Run and Outcome;</li><li>WorkDataPort and Outbox interfaces;</li><li>Provider capability negotiation and fallback;</li><li>credential isolation and revocation;</li><li>workflow promotion criteria;</li><li>verifier isolation requirements;</li><li>HOLD ownership and timeout;</li><li>cost budgets and Registry requirements for SME deployments.</li></ul><p>这些议题将通过工程证据、实施实验与显式版本更新逐项收口。</p>`,54)])])}const g=a(t,[["render",o]]);export{u as __pageData,g as default};
